css:
.convergence-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf4;
    background: radial-gradient(120% 90% at 50% 0%, #16202e 0%, #0e1620 55%, #0a111a 100%);
    border-radius: 18px;
}

.convergence-container * {
    box-sizing: border-box;
}

.convergence-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #0c1722 0%, #143042 55%, #0e3a4a 100%);
    border: 1px solid rgba(64, 224, 208, 0.18);
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

.convergence-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.convergence-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #ff5a5f;
    background: rgba(255, 90, 95, 0.10);
    border: 1px solid rgba(255, 90, 95, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.convergence-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #b9c6d6;
}

.convergence-layers {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 18px;
}

.convergence-layer {
    border-radius: 14px;
    padding: 14px 18px;
    display: flex;
    flex-direction: column;
    gap: 3px;
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.convergence-layer-hot {
    background: linear-gradient(100deg, rgba(64, 224, 208, 0.16) 0%, rgba(64, 224, 208, 0.05) 100%);
    border-left: 5px solid #40e0d0;
}

.convergence-layer-cold {
    background: linear-gradient(100deg, rgba(120, 140, 160, 0.14) 0%, rgba(120, 140, 160, 0.04) 100%);
    border-left: 5px solid #7c8da0;
}

.convergence-layer-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #ffffff;
}

.convergence-layer-hot .convergence-layer-name { color: #5bead9; }
.convergence-layer-cold .convergence-layer-name { color: #aebccd; }

.convergence-layer-meta {
    font-size: 0.82rem;
    color: #9fb0c2;
    line-height: 1.4;
}

.convergence-layer-arrow {
    align-self: center;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    color: #40e0d0;
}

.convergence-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb0c2;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.convergence-period-counter #currentDay,
.convergence-period-counter #maxPeriods {
    font-weight: 800;
    color: #40e0d0;
}

.convergence-round-name {
    background: rgba(64, 224, 208, 0.14);
    color: #5bead9;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.convergence-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff8a8d;
    background: rgba(255, 90, 95, 0.12);
    border: 1px solid rgba(255, 90, 95, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.convergence-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.convergence-status-card {
    background: linear-gradient(160deg, #16222f 0%, #111b27 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #40e0d0;
    border-right: 1px solid rgba(255, 255, 255, 0.04);
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
    border-left: 1px solid rgba(255, 255, 255, 0.04);
}

.convergence-card-value { border-top-color: #40e0d0; }
.convergence-card-ebit { border-top-color: #f5b14c; }
.convergence-card-recurring { border-top-color: #6ea8fe; }
.convergence-card-ecosystem { border-top-color: #b388ff; }

.convergence-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8497aa;
}

.convergence-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.convergence-card-value .convergence-value { color: #40e0d0; }
.convergence-card-ebit .convergence-value { color: #f5b14c; }
.convergence-card-recurring .convergence-value { color: #6ea8fe; }
.convergence-card-ecosystem .convergence-value { color: #b388ff; }

.convergence-sublabel {
    font-size: 0.75rem;
    color: #7e90a4;
    line-height: 1.4;
}

.convergence-card-ebit.convergence-ebit-danger { border-top-color: #ff5a5f; }
.convergence-card-ebit.convergence-ebit-danger .convergence-value { color: #ff5a5f; }
.convergence-card-ebit.convergence-ebit-good { border-top-color: #3ddc97; }
.convergence-card-ebit.convergence-ebit-good .convergence-value { color: #3ddc97; }

.convergence-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(160deg, #16222f 0%, #111b27 100%);
    border: 1px solid rgba(255, 90, 95, 0.22);
    color: #9fb0c2;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.convergence-threat-bar #threatDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff5a5f;
    font-weight: 800;
    white-space: nowrap;
    margin-left: 12px;
}

.convergence-threat-bar.convergence-threat-low #threatDisplay { color: #3ddc97; }
.convergence-threat-bar.convergence-threat-mid #threatDisplay { color: #f5b14c; }

.convergence-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #16222f 0%, #111b27 100%);
    border-left: 5px solid #40e0d0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.30);
}

.convergence-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.convergence-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.convergence-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #c2cfdd;
}

.convergence-briefing-text strong { color: #5bead9; }
.convergence-briefing-text em { color: #f5b14c; font-style: italic; }

.convergence-controls {
    background: linear-gradient(160deg, #16222f 0%, #111b27 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.30);
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.convergence-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid rgba(64, 224, 208, 0.20);
    padding-bottom: 8px;
}

.convergence-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d4dde8;
    margin: 14px 0 6px;
}

.convergence-container select,
.convergence-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c3c4e;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1822;
    color: #e8edf4;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.convergence-container select:focus,
.convergence-container input[type="number"]:focus {
    outline: none;
    border-color: #40e0d0;
    box-shadow: 0 0 0 3px rgba(64, 224, 208, 0.18);
}

.convergence-container select option {
    background-color: #0e1822;
    color: #e8edf4;
}

.convergence-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #40e0d0;
}

.convergence-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb0c2;
    margin-top: 6px;
}

.convergence-range-readout span:nth-child(2) {
    color: #40e0d0;
    font-weight: 800;
}

.convergence-hint {
    font-size: 0.8rem;
    color: #8497aa;
    margin-top: 8px;
    line-height: 1.45;
    font-style: italic;
}

.convergence-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.convergence-container .btn-primary {
    background: linear-gradient(135deg, #0e3a4a 0%, #1aa896 60%, #40e0d0 100%);
    border: none;
    color: #06121a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 10px 22px rgba(64, 224, 208, 0.26);
}

.convergence-container .btn-primary:hover {
    filter: brightness(1.08);
}

.convergence-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2c3c4e;
    color: #9fb0c2;
    background: transparent;
}

.convergence-coach {
    background: linear-gradient(160deg, #0c1722 0%, #122636 100%);
    border: 1px solid rgba(255, 90, 95, 0.18);
    color: #cdd9e6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.34);
}

.convergence-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ff8a8d;
    margin-bottom: 8px;
}

.convergence-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.convergence-coach-body strong { color: #5bead9; }
.convergence-coach-body em { color: #f5b14c; font-style: italic; }

.convergence-history,
.convergence-chart {
    background: linear-gradient(160deg, #16222f 0%, #111b27 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.30);
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.convergence-history h3,
.convergence-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.convergence-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c2cfdd;
}

.convergence-container table#usfHistoryTable th {
    background: rgba(64, 224, 208, 0.08);
    color: #5bead9;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(64, 224, 208, 0.22);
}

.convergence-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    color: #c2cfdd;
}

.convergence-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}

.convergence-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .convergence-container {
        padding: 14px;
    }
    .convergence-header h1 {
        font-size: 1.8rem;
    }
    .convergence-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .convergence-value {
        font-size: 2rem;
    }
    .convergence-clock {
        margin-left: 0;
    }
    .convergence-period-counter {
        font-size: 0.88rem;
    }
    .convergence-threat-bar {
        flex-direction: column;
        gap: 6px;
        align-items: flex-start;
    }
    .convergence-threat-bar #threatDisplay {
        margin-left: 0;
    }
    .convergence-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / board-debrief screen (convergence) ---- */
.convergence-cm { padding: 8px 4px 4px; color: #d7e0ea; }
.convergence-cm-head { text-align: center; margin-bottom: 18px; }
.convergence-cm-score { font-size: 3.4rem; font-weight: 800; line-height: 1; color: #40e0d0; }
.convergence-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7e9aa8; }
.convergence-cm-verdict { font-size: 1.2rem; font-weight: 700; margin-top: 8px; color: #eaf1f7; }
.convergence-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.76rem; font-weight: 700; vertical-align: middle; }
.convergence-cm-yes { background: rgba(64,224,208,0.16); color: #40e0d0; border: 1px solid rgba(64,224,208,0.5); }
.convergence-cm-no { background: rgba(255,90,95,0.13); color: #ff8b8f; border: 1px solid rgba(255,90,95,0.45); }
.convergence-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0; }
.convergence-cm-metric { flex: 1 1 110px; min-width: 96px; background: rgba(64,224,208,0.07); border: 1px solid rgba(64,224,208,0.22); border-radius: 10px; padding: 12px 8px; text-align: center; }
.convergence-cm-mv { display: block; font-size: 1.5rem; font-weight: 800; color: #40e0d0; }
.convergence-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #9fb0c2; text-transform: uppercase; letter-spacing: 0.04em; }
.convergence-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 4px 0 16px; }
.convergence-cm-chip { font-size: 0.78rem; font-weight: 600; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; }
.convergence-cm-chip-on { background: rgba(64,224,208,0.14); color: #7de9dd; border-color: rgba(64,224,208,0.4); }
.convergence-cm-chip-off { background: rgba(159,176,194,0.08); color: #8798a8; border-color: rgba(159,176,194,0.22); }
.convergence-cm-debrief-title { font-weight: 700; margin: 10px 0 6px; color: #eaf1f7; }
.convergence-cm-insights { margin: 0; padding-left: 20px; }
.convergence-cm-insights li { margin-bottom: 9px; line-height: 1.55; font-size: 0.92rem; color: #c3cfdb; }

