(function() {
    'use strict';

    class ConvergencePlayAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Convergence Play`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Helvetia Climatec AG).
            this.START_VALUE = 4;       // value-capture share of the energy-and-data layer (%)
            this.START_EBIT = 53;       // group EBIT (CHF M) — 11% of CHF 480M
            this.START_RECURRING = 2;   // annual recurring revenue (CHF M)
            this.START_ECOSYSTEM = 30;  // ecosystem strength (0–100)
            this.START_THREAT = 78;     // commoditization risk (0–100, lower safer)
            this.RD_CAP = 38;           // hard R&D budget cap (CHF M)
            this.EBIT_FLOOR = 31;       // ~6.5% margin commoditization floor (CHF M)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    ebit: this.START_EBIT,
                    recurring: this.START_RECURRING,
                    ecosystem: this.START_ECOSYSTEM,
                    threat: this.START_THREAT,
                    // Sticky run-defining penalty flags (set when an error is committed).
                    defendedBox: false,        // built a better box / saw value staying in hardware
                    narrativeNoAsset: false,   // pure software pivot with no defensible asset
                    channelRevolt: false,      // disintermediated / ignored the 1,200 installers
                    lockedIn: false,           // component-supplier lock-in inside the platform
                    overAmbitious: false,      // proprietary platform without the R&D headroom
                    paperReallocation: false,  // breached the cap / refused to cut hardware
                    rdSoftware: 0,
                    rdHardware: 0,
                    valueHistory: [this.START_VALUE],
                    ebitHistory: [this.START_EBIT],
                    recurringHistory: [this.START_RECURRING],
                    ecosystemHistory: [this.START_ECOSYSTEM],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    migration: `box`,
                    asset: `brand`,
                    exposure: `low`,
                    urgency: 35,
                    model: `betterbox`,
                    channel: `bypass`,
                    ramp: 40,
                    ecoChoice: `supplier`,
                    contingency: `hope`,
                    lockin: `unread`,
                    rdSoftware: 6,
                    rdHardware: 34,
                    defense: `narrative`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const mi = document.getElementById(`migrationInput`);
                const as = document.getElementById(`assetInput`);
                const ex = document.getElementById(`exposureInput`);
                const ur = document.getElementById(`urgencyInput`);
                if (mi) decisions.migration = mi.value;
                if (as) decisions.asset = as.value;
                if (ex) decisions.exposure = ex.value;
                if (ur) decisions.urgency = parseInt(ur.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const mo = document.getElementById(`modelInput`);
                const ch = document.getElementById(`channelInput`);
                const ra = document.getElementById(`rampInput`);
                if (mo) decisions.model = mo.value;
                if (ch) decisions.channel = ch.value;
                if (ra) decisions.ramp = parseInt(ra.value, 10);
                if (!Number.isFinite(decisions.ramp) || decisions.ramp < 0 || decisions.ramp > 100) {
                    warn(`warn_ramp_range`); return false;
                }
            } else if (round === 3) {
                const ec = document.getElementById(`ecoChoiceInput`);
                const co = document.getElementById(`contingencyInput`);
                const lo = document.getElementById(`lockinInput`);
                if (ec) decisions.ecoChoice = ec.value;
                if (co) decisions.contingency = co.value;
                if (lo) decisions.lockin = lo.value;
            } else if (round === 4) {
                const rs = document.getElementById(`rdSoftwareInput`);
                const rh = document.getElementById(`rdHardwareInput`);
                const df = document.getElementById(`defenseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rs) decisions.rdSoftware = parseFloat(rs.value);
                if (rh) decisions.rdHardware = parseFloat(rh.value);
                if (df) decisions.defense = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.rdSoftware) || decisions.rdSoftware < 0) {
                    warn(`warn_rd_value`); return false;
                }
                if (!Number.isFinite(decisions.rdHardware) || decisions.rdHardware < 0) {
                    warn(`warn_rd_value`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let valueDelta = 0, ebitDelta = 0, recurringDelta = 0, ecoDelta = 0, threatDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the convergence and the value migration (Common Error 1: defending the box).
                switch (d.migration) {
                    case `layer`: valueDelta += 3; threatDelta -= 8; ecoDelta += 4; coachKey = `coach_r1_layer`; break;
                    case `box`: ds.defendedBox = true; valueDelta -= 1; threatDelta += 10; coachKey = `coach_r1_box`; break;
                    case `nowhere`: ds.defendedBox = true; threatDelta += 14; coachKey = `coach_r1_nowhere`; break;
                }

                switch (d.asset) {
                    case `installed`: valueDelta += 4; ecoDelta += 8; recurringDelta += 1; threatDelta -= 8; break;
                    case `brand`: ecoDelta += 1; threatDelta += 3; coachKey = `coach_r1_brand`; break;
                    case `patents`: ds.defendedBox = true; threatDelta += 6; coachKey = `coach_r1_patents`; break;
                }

                switch (d.exposure) {
                    case `mid`: threatDelta -= 6; ecoDelta += 3; break;
                    case `low`: threatDelta += 6; coachKey = `coach_r1_explow`; break;
                    case `ignore`: threatDelta += 9; coachKey = `coach_r1_expignore`; break;
                }

                // Urgency = how seriously the convergence shock is taken.
                if (d.urgency >= 65) { threatDelta -= 6; ecoDelta += 3; }
                else if (d.urgency <= 25) { threatDelta += 6; ecoDelta -= 2; }

                summaryKey = (d.migration === `layer` && d.asset === `installed` && d.exposure === `mid`) ? `sum_r1_good` : `sum_r1_weak`;
                if (d.migration === `layer` && d.asset === `installed` && d.exposure === `mid` && d.urgency >= 65) coachKey = `coach_r1_sharp`;
            } else if (round === 2) {
                // Reconfigure the business model (Common Errors 1 & 2).
                const ramp = d.ramp / 100;

                if (d.model === `betterbox`) {
                    // Defending the legacy product layer (decision tree #1).
                    ds.defendedBox = true;
                    valueDelta -= 1;
                    ebitDelta -= 4;
                    threatDelta += 14;
                    recurringDelta += 0;
                    coachKey = `coach_r2_betterbox`;
                } else if (d.model === `software`) {
                    // Narrative without an anchored asset depends on whether R1 named the installed base.
                    if (d.asset !== `installed`) {
                        ds.narrativeNoAsset = true;
                        valueDelta += 4;
                        ebitDelta -= 6 - (1 - ramp) * 3;   // faster ramp on a hollow narrative burns more EBIT
                        threatDelta += 4;
                        recurringDelta += 2 * ramp;
                        coachKey = `coach_r2_software`;
                    } else {
                        // Software, but at least anchored on the base — partial.
                        valueDelta += 8;
                        ebitDelta -= 3;
                        threatDelta -= 4;
                        recurringDelta += 5 * ramp;
                        coachKey = `coach_r2_softwareanchored`;
                    }
                } else { // caas — climate-as-a-service on the installed base
                    valueDelta += 12;
                    threatDelta -= 14;
                    recurringDelta += 6 + ramp * 8;
                    ebitDelta += 1 - (ramp > 0.85 ? 4 : 0);   // a sane ramp protects EBIT; flooring it strains the transition
                    ecoDelta += 6;
                    coachKey = `coach_r2_caas`;
                    if (ramp >= 0.9) { threatDelta += 5; coachKey = `coach_r2_caasfast`; }
                    else if (ramp <= 0.15) { recurringDelta -= 4; valueDelta -= 3; coachKey = `coach_r2_caasslow`; }
                }

                // Channel cannibalization — the 1,200 installers (decision tree #6).
                switch (d.channel) {
                    case `codesign`: ecoDelta += 10; threatDelta -= 8; recurringDelta += 2; break;
                    case `bypass`: ds.channelRevolt = true; ecoDelta -= 12; recurringDelta -= 3; threatDelta += 8; if (coachKey === `coach_default` || d.model === `caas`) coachKey = `coach_r2_bypass`; break;
                    case `ignore`: ds.channelRevolt = true; ecoDelta -= 7; threatDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r2_channelignore`; break;
                }

                summaryKey = (d.model === `caas` && d.channel === `codesign`) ? `sum_r2_good` :
                             (d.model === `betterbox` ? `sum_r2_box` :
                             (ds.narrativeNoAsset ? `sum_r2_narrative` :
                             (ds.channelRevolt ? `sum_r2_channel` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Pick the partner ecosystem (Common Errors 3 & 4).
                switch (d.ecoChoice) {
                    case `alliance`:
                        // Utility-led open alliance — keeps the customer relationship, shares the layer.
                        valueDelta += 10; ecoDelta += 16; recurringDelta += 4; threatDelta -= 12; coachKey = `coach_r3_alliance`; break;
                    case `coalition`:
                        // European manufacturer coalition — scale, slower, decent control.
                        valueDelta += 7; ecoDelta += 12; recurringDelta += 2; threatDelta -= 8; coachKey = `coach_r3_coalition`; break;
                    case `supplier`:
                        // Component supplier inside the dominant platform — lock-in unless explicitly contracted.
                        ecoDelta += 4; recurringDelta += 1; threatDelta += 4;
                        if (d.lockin !== `shared`) {
                            ds.lockedIn = true; valueDelta -= 4; ebitDelta -= 5; threatDelta += 10; coachKey = `coach_r3_supplier`;
                        } else {
                            valueDelta += 5; threatDelta -= 4; coachKey = `coach_r3_supplierfair`;
                        }
                        break;
                    case `proprietary`:
                        // Build the Helvetia OS — control & margin, but resource-fragile under the cap.
                        valueDelta += 6; ecoDelta += 6; threatDelta -= 2; ebitDelta -= 3;
                        ds.overAmbitious = true;   // provisionally; cleared in R4 only if software R&D funds it
                        coachKey = `coach_r3_proprietary`;
                        break;
                }

                // Contingency for the utility going exclusive (disruption resilience).
                switch (d.contingency) {
                    case `diversify`: ecoDelta += 8; threatDelta -= 8; valueDelta += 2; break;
                    case `concede`: ecoDelta -= 4; valueDelta -= 3; threatDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_concede` : coachKey; break;
                    case `hope`: ecoDelta -= 8; threatDelta += 8; if (coachKey === `coach_default`) coachKey = `coach_r3_hope`; break;
                }

                // Lock-in reading (interacts with supplier above; rewards keeping the relationship).
                switch (d.lockin) {
                    case `shared`: valueDelta += 4; threatDelta -= 5; ecoDelta += 3; break;
                    case `full`: ebitDelta -= 3; ecoDelta += 1; break;   // total control costs cash
                    case `unread`: threatDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_lockinblind`; break;
                }

                summaryKey = ((d.ecoChoice === `alliance` || d.ecoChoice === `coalition`) && d.contingency === `diversify`) ? `sum_r3_good` :
                             (ds.lockedIn ? `sum_r3_lockin` :
                             (d.ecoChoice === `proprietary` ? `sum_r3_proprietary` :
                             (d.contingency === `hope` ? `sum_r3_fragile` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Reallocate R&D under the cap and defend the plan (Common Error 5).
                const soft = Number(d.rdSoftware) || 0;
                const hard = Number(d.rdHardware) || 0;
                const total = soft + hard;
                ds.rdSoftware = soft;
                ds.rdHardware = hard;

                if (total > this.RD_CAP + 0.001) {
                    // Breached the cap = a wish list, not a reallocation (decision tree #5).
                    ds.paperReallocation = true;
                    ebitDelta -= 6; valueDelta -= 4; threatDelta += 10; ecoDelta -= 4;
                    coachKey = `coach_r4_paper`;
                } else if (soft < 10) {
                    // Protected hardware, underfunded the new model — the reallocation never happened.
                    ds.paperReallocation = true;
                    valueDelta -= 3; threatDelta += 6;
                    coachKey = `coach_r4_underfunded`;
                } else if (soft >= 12 && soft <= 20) {
                    // Genuine reallocation in the realistic band (~CHF 14M software).
                    valueDelta += 8; recurringDelta += 5; ebitDelta += 3; threatDelta -= 10; ecoDelta += 6;
                    ds.overAmbitious = false;   // a proprietary play funded at this level is no longer under-resourced... mostly
                    coachKey = `coach_r4_reallocated`;
                } else {
                    // Over-rotated to software (>20) — starved the hardware that still earns the EBIT.
                    valueDelta += 5; recurringDelta += 4; ebitDelta -= 4; threatDelta -= 4;
                    coachKey = `coach_r4_overrotate`;
                }

                // A proprietary platform needs serious software R&D, or it stays under-resourced.
                if (d.ecoChoice === `proprietary` && soft < 16) {
                    ds.overAmbitious = true;
                } else if (d.ecoChoice === `proprietary` && soft >= 16 && total <= this.RD_CAP + 0.001) {
                    ds.overAmbitious = false;
                }

                // The 3-minute board defense.
                switch (d.defense) {
                    case `protect`: ebitDelta += 4; ecoDelta += 4; threatDelta -= 6; valueDelta += 2; if (coachKey === `coach_r4_reallocated`) coachKey = `coach_r4_protect`; break;
                    case `narrative`: ebitDelta -= 2; threatDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r4_narrative`; break;
                    case `hardware`: valueDelta -= 3; threatDelta += 4; ecoDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r4_reassure`; break;
                }

                if (d.conviction >= 60) { threatDelta -= 4; ecoDelta += 3; }
                else if (d.conviction <= 25) { threatDelta += 4; ecoDelta -= 2; }

                summaryKey = (soft >= 12 && soft <= 20 && total <= this.RD_CAP + 0.001 && d.defense === `protect`) ? `sum_r4_good` :
                             (ds.paperReallocation ? `sum_r4_paper` : `sum_r4_weak`);
            }

            // ---- Apply deltas (clamped). ----
            ds.value = Math.max(0, Math.min(100, Math.round((ds.value + valueDelta) * 10) / 10));
            ds.ebit = Math.max(this.EBIT_FLOOR - 6, Math.round((ds.ebit + ebitDelta) * 10) / 10);
            ds.recurring = Math.max(0, Math.round((ds.recurring + recurringDelta) * 10) / 10);
            ds.ecosystem = Math.max(0, Math.min(100, Math.round(ds.ecosystem + ecoDelta)));
            ds.threat = Math.max(0, Math.min(100, Math.round(ds.threat + threatDelta)));

            // ---- Sticky-flag KPI CAPS (a later good round cannot wash these out). ----
            if (ds.defendedBox) {
                ds.value = Math.min(ds.value, 18);          // value cannot be recaptured from the box layer
            }
            if (ds.narrativeNoAsset) {
                ds.ebit = Math.min(ds.ebit, this.START_EBIT - 4);  // burning EBIT on a hollow narrative
                ds.recurring = Math.min(ds.recurring, 9);
            }
            if (ds.lockedIn) {
                ds.value = Math.min(ds.value, 14);          // the platform owns the recaptured value
                ds.ebit = Math.min(ds.ebit, this.START_EBIT - 2);  // platform tax on a commoditized box
            }
            if (ds.channelRevolt) {
                ds.ecosystem = Math.min(ds.ecosystem, 48);  // the installers became opponents
                ds.recurring = Math.min(ds.recurring, 11);
            }
            if (ds.overAmbitious) {
                ds.recurring = Math.min(ds.recurring, 12);  // the OS is years away from earning
                ds.value = Math.min(ds.value, 26);
            }
            if (ds.paperReallocation) {
                ds.value = Math.min(ds.value, 20);
                ds.ebit = Math.min(ds.ebit, this.START_EBIT);
            }

            ds.valueHistory.push(ds.value);
            ds.ebitHistory.push(ds.ebit);
            ds.recurringHistory.push(ds.recurring);
            ds.ecosystemHistory.push(ds.ecosystem);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period.
            // express/results_utils.php::express_extractMetrics reads domainState.performance.overallScore.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                value: ds.value,
                valueDelta: Math.round(valueDelta * 10) / 10,
                ebit: ds.ebit,
                ebitDelta: Math.round(ebitDelta * 10) / 10,
                recurring: ds.recurring,
                ecosystem: ds.ecosystem,
                threat: ds.threat,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: ds.performance.overallScore,
                score: ds.performance.overallScore
            };
        }

        _threatLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`threat_high`);
            if (v >= 35) return t(`threat_mid`);
            return t(`threat_low`);
        }

        _fmtChf(v) {
            return `CHF ${Math.round(Number(v))}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`ebitDisplay`, `domainState.ebit`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.convergence-card-ebit`);
                if (card) {
                    card.classList.toggle(`convergence-ebit-danger`, n < self.START_EBIT - 0.5);
                    card.classList.toggle(`convergence-ebit-good`, n >= self.START_EBIT + 4);
                }
                return self._fmtChf(n);
            });

            uiManager.bind(`recurringDisplay`, `domainState.recurring`, (v) => self._fmtChf(v));
            uiManager.bind(`ecosystemDisplay`, `domainState.ecosystem`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`threatDisplay`, `domainState.threat`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.convergence-threat-bar`);
                if (bar) {
                    bar.classList.toggle(`convergence-threat-low`, n < 35);
                    bar.classList.toggle(`convergence-threat-mid`, n >= 35 && n < 60);
                }
                return self._threatLabel(n);
            });

            // Urgency slider readout.
            const ur = document.getElementById(`urgencyInput`);
            const urReadout = document.getElementById(`urgencyReadout`);
            if (ur && urReadout) {
                urReadout.textContent = ur.value;
                ur.addEventListener(`input`, function() { urReadout.textContent = ur.value; });
            }

            // Ramp slider readout.
            const ra = document.getElementById(`rampInput`);
            const raReadout = document.getElementById(`rampReadout`);
            if (ra && raReadout) {
                raReadout.textContent = ra.value;
                ra.addEventListener(`input`, function() { raReadout.textContent = ra.value; });
            }

            // R&D total readout (software + hardware vs the cap).
            const rs = document.getElementById(`rdSoftwareInput`);
            const rh = document.getElementById(`rdHardwareInput`);
            const rt = document.getElementById(`rdTotalReadout`);
            const recompute = function() {
                if (!rt) return;
                const s = parseFloat(rs ? rs.value : 0) || 0;
                const h = parseFloat(rh ? rh.value : 0) || 0;
                rt.textContent = Math.round((s + h) * 10) / 10;
                rt.style.color = (s + h) > self.RD_CAP ? `#ff5a5f` : `#40e0d0`;
            };
            if (rs) rs.addEventListener(`input`, recompute);
            if (rh) rh.addEventListener(`input`, recompute);
            recompute();
        }

        getChartConfig() {
            return {
                convergenceChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_value`, `Value-capture share (%)`),
                                data: [],
                                borderColor: `#40e0d0`,
                                backgroundColor: `rgba(64,224,208,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#40e0d0`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_ebit`, `Group EBIT (CHF M)`),
                                data: [],
                                borderColor: `#f5b14c`,
                                backgroundColor: `rgba(245,177,76,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#f5b14c`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_ecosystem`, `Ecosystem strength (0–100)`),
                                data: [],
                                borderColor: `#b388ff`,
                                backgroundColor: `rgba(179,136,255,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b388ff`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_recurring`, `Recurring revenue (CHF M)`),
                                data: [],
                                borderColor: `#6ea8fe`,
                                backgroundColor: `rgba(110,168,254,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6ea8fe`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb0c2`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7e90a4` }, grid: { color: `rgba(255,255,255,0.06)` },
                                title: { display: true, text: this._cl(`axis_scale`, `0–100 · % · CHF M`), color: `#7e90a4` }
                            },
                            x: {
                                ticks: { color: `#7e90a4` }, grid: { color: `rgba(255,255,255,0.04)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#7e90a4` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                convergenceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory.map((v) => Math.round(v)) },
                        { data: ds.ebitHistory.map((v) => Math.round(v)) },
                        { data: ds.ecosystemHistory },
                        { data: ds.recurringHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            const value = Math.round(ds.value);
            const ebit = Math.round(ds.ebit);
            const recurring = Math.round(ds.recurring);
            const ecosystem = Math.round(ds.ecosystem);
            const ebitScore = Math.max(0, Math.min(100, ((ebit - this.EBIT_FLOOR) / (62 - this.EBIT_FLOOR)) * 100));
            const recurringScore = Math.max(0, Math.min(100, (recurring / 22) * 100));
            return Math.round(value * 0.32 + ebitScore * 0.26 + ecosystem * 0.24 + recurringScore * 0.18);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _gradeLabel(perf) {
            const map = {
                "Value Stranded": `grade_stranded`,
                "Convergence Captured": `grade_captured`,
                "Value Reeled In": `grade_reeled`,
                "Defended the Box": `grade_box`,
                "Locked In": `grade_lockin`,
                "Narrative Without Asset": `grade_narrative`,
                "Over-Ambitious Platform": `grade_proprietary`,
                "Paper Reallocation": `grade_paper`,
                "Mixed Reconfiguration": `grade_mixed`
            };
            const key = map[perf];
            return key ? this._cl(key, perf) : perf;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const ebit = Math.round(ds.ebit);
            const recurring = Math.round(ds.recurring);
            const ecosystem = Math.round(ds.ecosystem);

            const anyFlag = ds.defendedBox || ds.narrativeNoAsset || ds.lockedIn ||
                            ds.channelRevolt || ds.overAmbitious || ds.paperReallocation;

            // Composite (0–100): value-capture, EBIT vs base, ecosystem, recurring.
            const ebitScore = Math.max(0, Math.min(100, ((ebit - this.EBIT_FLOOR) / (62 - this.EBIT_FLOOR)) * 100));
            const recurringScore = Math.max(0, Math.min(100, (recurring / 22) * 100));
            const composite = Math.round(
                value * 0.32 + ebitScore * 0.26 + ecosystem * 0.24 + recurringScore * 0.18
            );

            const captured = value >= 35;
            const ebitProtected = ebit >= 58;
            const strongEcosystem = ecosystem >= 70;
            const recurringBuilt = recurring >= 14;

            // Pattern attribution from the sticky flags.
            let pattern = `mixed`;
            if (ds.defendedBox) pattern = `box`;
            else if (ds.lockedIn) pattern = `lockin`;
            else if (ds.narrativeNoAsset) pattern = `narrative`;
            else if (ds.overAmbitious) pattern = `proprietary`;
            else if (ds.paperReallocation) pattern = `paper`;
            else if (ds.channelRevolt) pattern = `channel`;
            else if (captured && ebitProtected && strongEcosystem) pattern = `captured`;

            // Verdict — the top verdict is GATED by every flag plus the four thresholds.
            let performance = `Value Stranded`;
            if (captured && ebitProtected && strongEcosystem && recurringBuilt && !anyFlag && composite >= 75) {
                performance = `Convergence Captured`;
            } else if (!anyFlag && captured && ebitProtected && composite >= 62) {
                performance = `Value Reeled In`;
            } else if (ds.defendedBox) {
                performance = `Defended the Box`;
            } else if (ds.lockedIn) {
                performance = `Locked In`;
            } else if (ds.narrativeNoAsset) {
                performance = `Narrative Without Asset`;
            } else if (ds.overAmbitious) {
                performance = `Over-Ambitious Platform`;
            } else if (ds.paperReallocation) {
                performance = `Paper Reallocation`;
            } else if (composite >= 52) {
                performance = `Mixed Reconfiguration`;
            }

            const insights = [];
            if (performance === `Convergence Captured`) insights.push(window.mySimulation.t(`insight_captured`));
            else if (pattern === `box`) insights.push(window.mySimulation.t(`insight_box`));
            else if (pattern === `lockin`) insights.push(window.mySimulation.t(`insight_lockin`));
            else if (pattern === `narrative`) insights.push(window.mySimulation.t(`insight_narrative`));
            else if (pattern === `proprietary`) insights.push(window.mySimulation.t(`insight_proprietary`));
            else if (pattern === `paper`) insights.push(window.mySimulation.t(`insight_paper`));
            else if (pattern === `channel`) insights.push(window.mySimulation.t(`insight_channel`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ebitProtected && !ds.defendedBox && !ds.lockedIn) insights.push(window.mySimulation.t(`insight_ebit_low`));
            if (!captured && !ds.defendedBox) insights.push(window.mySimulation.t(`insight_value_low`));
            if (ds.channelRevolt && pattern !== `channel`) insights.push(window.mySimulation.t(`insight_channel_side`));
            if (captured && ebitProtected && ecosystem < 70) insights.push(window.mySimulation.t(`insight_eco_thin`));

            return {
                value: value,
                ebit: ebit,
                recurring: recurring,
                ecosystem: ecosystem,
                captured: captured,
                ebitProtected: ebitProtected,
                strongEcosystem: strongEcosystem,
                recurringBuilt: recurringBuilt,
                anyFlag: anyFlag,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                met: (captured && ebitProtected && strongEcosystem && recurringBuilt && !anyFlag && composite >= 75),
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function (k) { return window.mySimulation.t(k); }
                : function (k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const verdict = s.performanceLabel || s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="convergence-cm-badge convergence-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="convergence-cm-badge convergence-cm-no">` + T(`cm_notmet`) + `</span>`;
            const chip = function (ok, key) {
                return `<span class="convergence-cm-chip ` + (ok ? `convergence-cm-chip-on` : `convergence-cm-chip-off`) + `">`
                    + (ok ? `✓ ` : `· `) + T(key) + `</span>`;
            };
            const chips = chip(!!s.captured, `cm_b_captured`) + chip(!!s.ebitProtected, `cm_b_ebit`)
                + chip(!!s.strongEcosystem, `cm_b_eco`) + chip(!!s.recurringBuilt, `cm_b_recurring`);
            const md = function (val, key) {
                return `<div class="convergence-cm-metric"><span class="convergence-cm-mv">` + val
                    + `</span><span class="convergence-cm-ml">` + T(key) + `</span></div>`;
            };
            const metrics = md(Math.round(s.value || 0) + `%`, `cm_m_value`)
                + md(self._fmtChf(s.ebit || 0), `cm_m_ebit`)
                + md(Math.round(s.ecosystem || 0), `cm_m_ecosystem`)
                + md(self._fmtChf(s.recurring || 0), `cm_m_recurring`);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function (t) { return `<li>` + t + `</li>`; }).join(``);
            return `<div class="convergence-cm">`
                + `<div class="convergence-cm-head">`
                +   `<div class="convergence-cm-score">` + score + `<span class="convergence-cm-score-max">/100</span></div>`
                +   `<div class="convergence-cm-verdict">` + verdict + ` ` + badge + `</div>`
                + `</div>`
                + `<div class="convergence-cm-metrics">` + metrics + `</div>`
                + `<div class="convergence-cm-chips">` + chips + `</div>`
                + `<div class="convergence-cm-debrief-title">` + T(`cm_debrief`) + `</div>`
                + `<ul class="convergence-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.defendedBox) return window.mySimulation.t(`hint_box`);
            if (ds.lockedIn) return window.mySimulation.t(`hint_lockin`);
            if (ds.paperReallocation) return window.mySimulation.t(`hint_paper`);
            if (ds.narrativeNoAsset) return window.mySimulation.t(`hint_narrative`);
            if (ds.overAmbitious) return window.mySimulation.t(`hint_proprietary`);
            if (ds.channelRevolt) return window.mySimulation.t(`hint_channel`);
            if (ds.threat >= 65) return window.mySimulation.t(`hint_threat`);
            if (ds.value >= 35 && ds.ebit >= 58 && ds.ecosystem >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.ebit`, label: `EBIT`, i18nKey: `col_ebit`, formatter: (v) => self._fmtChf(v) },
                { key: `results.recurring`, label: `Recurring`, i18nKey: `col_recurring`, formatter: (v) => self._fmtChf(v) },
                { key: `results.ecosystem`, label: `Ecosystem`, i18nKey: `col_ecosystem`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

